/* Interactive design fixture. No API calls, accounts, database or real transactions. */
const KUT_DESIGN = window.KUT_DESIGN;
const state = { wants:['alex','ellis'], available:['charlie'], goals:null, nominees:{}, saved:false, balance:500, packOpened:false, category:null, count:5 };
const titles = {market:'Market',adminreports:'Session reports',listing:'Alex Example',home:'This week in KUT',wanted:'Wanted cards',tradecards:'Trade cards',matches:'Trade matches',swap:'Review swap',report:'Your match report',saved:'Report saved',recap:'Friday, in good company',attendance:'Publish attendance',editions:'Special editions',packs:'Packs',value:'Club Value',copies:'Your copies',account:'Settings',offers:'Offers',collection:'Collection',leaderboard:'Leaderboard',messages:'Messages'};
const categories = {team:'Team Player',wall:'The Wall',vibes:'Great Vibes'};
const categoryHelp = {team:'Involved others and played for the team.',wall:'Defending or goalkeeping worth a nod.',vibes:'Made the evening a good one.'};
const app = document.getElementById('app');
const dialog = document.getElementById('picker');
let returnFocus = null;
const icon = name => KUT_DESIGN.icons[name] || KUT_DESIGN.icons.IconCollection;
const player = id => KUT_DESIGN.players.find(p=>p.id===id);
let cardSequence=0;
const card = id => KUT_DESIGN.cards[id].replaceAll(`shirt-arc-${id}-`, `shirt-arc-${id}-${++cardSequence}-`);
const esc = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link = (screen,label,cls='') => `<a href="?screen=${screen}" class="${cls}">${label}</a>`;
const button = (act,label,cls='',extra='') => `<button type="button" data-act="${act}" class="btn ${cls}" ${extra}>${label}</button>`;
const screen = () => new URL(location.href).searchParams.get('screen') || 'wanted';
const primaryKey = s => ['wanted','tradecards','value','copies','collection'].includes(s)?'collection':['offers','listing','market'].includes(s)?'market':s==='packs'?'packs':s==='leaderboard'?'leaderboard':'home';
const primaryItems = [['home','Home','IconHome'],['collection','Collection','IconCollection'],['packs','Packs','IconPack'],['market','Market','IconMarket'],['leaderboard','Leaderboard','IconLeaderboard']];
function chrome(s){const active=primaryKey(s);const nav=primaryItems.map(([id,title,i])=>link(id,`${icon(i)}<span>${title}</span>`,id===active?'active':'')).join('');return `<header class="topbar"><div class="bar-inner">${link('home','<span class="pennant"></span>KUT','brand')}<nav class="primary" aria-label="Primary">${nav}</nav><div class="chrome"><span class="balance" aria-label="${state.balance} KUT Coins">${icon('IconCoin')}${state.balance}</span><a class="round" href="?screen=messages" aria-label="Messages">${icon('IconMessages')}</a><a href="?screen=account" class="round avatar" aria-label="Account and settings">AE</a></div></div></header><nav class="bottomnav" aria-label="Primary mobile">${nav}</nav>`;}
function head(s,kicker,description='',action=''){return `<header class="pagehead"><p class="kicker">${kicker}</p><div class="headrow"><h1>${titles[s]}</h1>${action}</div>${description?`<p class="intro">${description}</p>`:''}</header>`;}
function tabs(kind,active){const entries=kind==='collection'?[['collection','Album'],['copies','Manage'],['wanted','Wanted']]:[['market','Buy'],['offers','Offers']];return `<nav class="tabs" aria-label="${kind}">${entries.map(([id,label])=>`<a href="?screen=${id}" ${label===active?'aria-current="page"':''} class="${label===active?'active':''}">${label}</a>`).join('')}</nav>`;}
function footer(){return `<footer class="review-foot">Fictional data · interactive design prototype<br><a href="index.html" target="_top">All screen designs</a>${link('attendance','Admin attendance')}${link('editions','Edition scaffolding')}</footer>`;}
function note(text){return `<div class="callout"><p>${text}</p></div>`;}
function wantScreen(){return `${head('wanted','Your collection','A wanted card. A familiar name. A conversation at football.',button('add-wants','+ Add cards'))}${tabs('collection','Wanted')}<div class="section-head"><p class="muted small">${state.wants.length} wanted · your list stays private</p>${link('tradecards','My trade cards','btn text')}</div><div id="availability-status"></div><div class="columns"><section>${state.wants.length?`<div class="card-grid">${state.wants.map(id=>`<article class="card-tile">${card(id)}<div class="card-caption"><b>${player(id).displayName}</b><span class="muted">Live edition</span></div>${id==='alex'?`<div class="availability-note"><span class="pill green">Open to trading</span><p><b>Bea Test</b> has offered this card for trading.</p>${button('conversation','Copy message','secondary')}</div>`:`<p class="muted small availability-note">Nobody has offered this card for trading yet.</p>`}${id==='alex'?link('listing','Listed from 130 coins →','btn text'):''}${button(`remove-want:${id}`,'Remove','text',`aria-label="Remove ${player(id).displayName} from wanted cards"`)}</article>`).join('')}</div>`:`<div class="empty"><h2>Who is missing?</h2><p class="muted">Add a card you want. See who is open to trading it.</p>${button('add-wants','Add cards')}</div>`}</section><aside class="panel stack"><h2>Start with a conversation.</h2><p class="muted">Contact Bea and agree what works for both of you.</p><p class="small muted">Nobody needs to want one of your cards first. A name here means open to a conversation, not a reserved card.</p>${button('trade-help','How to complete a trade','secondary full')}<div class="rule"></div><p class="muted small">Have a spare? Choose which copies other members can ask you about.</p>${link('tradecards','Choose trade cards','btn secondary full')}${button('refresh-availability','Refresh availability','text full')}</aside></div>`;}
function tradeCards(){return `${link('wanted','← Wanted cards','back')}${head('tradecards','Your collection','Let a spare start a conversation.')}${note('<b>You choose what to share.</b><br>Members who want this card can see your name. Your other cards stay private.')}<div class="columns"><section>${['charlie','dana','bea'].map((id,i)=>`<div class="row"><div class="thumb">${card(id)}</div><div class="grow"><h3>${player(id).displayName}</h3><p class="muted small">Live · ${i===0?'2 copies · copy 2 selected':'1 copy'}</p><p class="small ${state.available.includes(id)?'positive':'muted'}">${state.available.includes(id)?'Open to trading':'Private'}</p></div><button class="switch" aria-label="Open to trading: ${player(id).displayName}" aria-pressed="${state.available.includes(id)}" data-act="available:${id}"></button></div>`).join('')}</section><aside class="panel stack"><h2>Keep it simple.</h2><p class="muted">Someone who wants your card can spot your name and contact you about it.</p><p class="small muted">This does not list, reserve or trade a card. You can turn it off whenever you like.</p>${link('value','See how duplicate value works →')}</aside></div><div class="section">${link('wanted','Back to wanted cards','btn')}</div>`;}
function marketScreen(){return `${head('market','Transfer market')}${tabs('market','Buy')}<div class="card-grid">${['alex','dana','ellis'].map(id=>`<article class="card-tile">${card(id)}<p class="card-caption"><b>${player(id).displayName}</b><span class="muted">Existing public listing</span></p>${link('listing','View listing','btn secondary')}</article>`).join('')}</div>`;}
function reportScreen(){return `${link('home','← Home','back')}${head('report','Friday football · 4 September')}<div class="flow"><div class="section-head"><span class="pill gold">Closes Sat 5 Sep, 21:30</span><span class="small muted">About a minute</span></div><form id="report-form"><section class="panel"><h2>Your goals</h2><p class="muted small" style="margin-top:10px">How many goals did you score? Zero is a perfectly good answer.</p><div class="goals" role="group" aria-label="Goals scored">${[0,1,2,3,4,5].map(n=>`<button type="button" class="goal" data-act="goal:${n}" aria-pressed="${state.goals===n}">${n}</button>`).join('')}</div><div class="goal-other"><label for="goal-count">Another number</label><input id="goal-count" class="input" type="text" inputmode="numeric" pattern="[0-9]*" placeholder="6+" value="${state.goals>5?state.goals:''}" maxlength="2"></div><div id="goal-confirm"></div><p class="small muted" style="margin-top:12px">Enter your goals, including zero, to complete your report.</p></section><section class="section"><p class="kicker">A nod to your teammates</p><h2 style="margin-top:12px">Who made the evening?</h2><p class="muted small" style="margin-top:10px">Choose a different teammate for each, or explicitly skip. Three skips is fine.</p>${Object.keys(categories).map(key=>`<div class="kudos-row"><div><h3>${categories[key]}</h3><p>${categoryHelp[key]}</p></div>${button(`nominate:${key}`,state.nominees[key]?esc(player(state.nominees[key]).displayName):Object.hasOwn(state.nominees,key)?'Skipped · change':'Choose teammate','secondary')}</div>`).join('')}</section><div id="report-error"></div><div class="savearea">${!state.saved?button('save-draft','Save draft','text full'):""}<button class="btn full" type="submit">${state.saved?'Save changes':'Submit report · earn 50 coins'}</button><p class="small muted">${state.saved?'Your 50-coin reward has already been received.':'Enter goals and choose or skip each category. +50 coins once per session.'} Editable until Sat 5 Sep, 21:30.</p></div></form></div>`;}
function savedScreen(){return `${link('home','← Home','back')}${head('saved','Friday football · 4 September')}<div class="flow panel"><div class="saved-mark">✓</div><span class="pill green">+50 KUT Coins received</span><h2 style="margin-top:16px">You have had your say.</h2><p class="muted" style="margin-top:12px">Your report is complete. You can change it until Saturday at 21:30.</p><table class="ledger section"><tbody><tr><td>Your goals</td><td>${state.goals??'Not reported'}</td></tr>${Object.keys(categories).map(key=>`<tr><td>${categories[key]}</td><td>${state.nominees[key]?esc(player(state.nominees[key]).displayName):'Skipped'}</td></tr>`).join('')}</tbody></table><div class="actions section">${link('report','Edit my report','btn secondary')}${link('home','Back to Home','btn text')}</div><p class="notice">250 coins for attendance + 50 for this report. Editing your answers does not pay again.</p></div>`;}
function recapScreen(){return `${link('home','← This week in KUT','back')}${head('recap','The TFH Chronicle · week 36','Twenty pairs of boots. A few good goals. Plenty of good company.')}<div class="columns"><section><div class="section-head"><h2>Friday's reported goals</h2><span class="pill green">Reports closed</span></div><p class="report-count">14 of 20 goal reports received · 17 reported goals</p><table class="ledger"><thead><tr><th>Player</th><th>Goals</th></tr></thead><tbody><tr><td>Alex Example</td><td>3</td></tr><tr><td>Charlie Fixture</td><td>2</td></tr><tr><td>Dana Demo</td><td>2</td></tr><tr><td>Seven other reporters</td><td>10</td></tr></tbody></table><p class="notice">Four members reported zero. Six have not reported. Goals are self-reported, not an official score.</p><div class="section"><h2>A little recognition</h2><div class="row"><div class="grow"><h3>Bea Test</h3><p class="muted small">Got stuck in for the team.</p></div><span class="pill green">Team Player</span></div><div class="row"><div class="grow"><h3>Dana Demo</h3><p class="muted small">Good company, on and off the ball.</p></div><span class="pill green">Great Vibes</span></div></div></section><aside class="panel stack"><p class="eyebrow">Your card · Alex Example</p><h2>A good night's form.</h2><table class="ledger"><tbody><tr><td>3 reported goals</td><td>+1.5 Form</td></tr><tr><td>Kudos this session</td><td>+0 Form</td></tr></tbody></table><p class="muted small">This evening's boost fades over the next four TFH sessions. Showing up remains the main driver of your rating.</p>${link('report&state=closed','View report','btn secondary full')}</aside></div>`;}
function adminAttendance(){return `${head('attendance','Club administration','Attendance first. Members take care of their own goal reports.')}<nav class="actions" aria-label="Admin sections">${link('attendance','Attendance','btn secondary')}${link('adminreports','Reports','btn text')}${link('editions','Editions','btn text')}</nav><form id="attendance-form" class="flow section"><div class="panel stack"><div><label class="label" for="session-date">Session date</label><input class="input" id="session-date" type="date" value="2026-09-04"></div><div><label class="label" for="session-type">Session</label><select id="session-type" class="input"><option>Friday</option><option>Monday</option><option>Other</option></select></div><div><label class="label" for="bibs">Who brought the bibs?</label><select class="input" id="bibs"><option>Dana Demo</option><option>Nobody</option><option>Alex Example</option></select></div></div><div class="section"><h2>Who was there?</h2><div class="search section">${icon('IconSearch')}<input aria-label="Search attendees" data-search="attendees" placeholder="Find a player"></div><div id="attendees">${KUT_DESIGN.players.map(p=>`<label class="checkrow" data-name="${p.displayName.toLowerCase()}"><input type="checkbox" class="checkbox" checked name="attendee" value="${p.id}">${p.displayName}</label>`).join('')}</div></div>${note('<b>Goals & kudos are handled next.</b><br>Attendees get 24 hours to send their own reports. Attendance rewards go out as soon as you publish. A completed self-report earns another 50 coins.')}<button class="btn full" type="submit">Publish attendance</button><div id="attendance-status"></div></form>`;}
function editionScreen(){return `${head('editions','Club administration')}<nav class="actions" aria-label="Admin sections">${link('attendance','Attendance','btn text')}${link('editions','Editions','btn secondary')}</nav><section class="editions section"><div class="empty"><div class="edition-empty">${icon('IconCollection')}<span class="eyebrow">Edition archive</span></div><h2>No special editions<br>have been issued.</h2><p class="muted" style="max-width:420px;margin:16px auto 0">A football moment, kept on a card.<br>When editions are introduced, their history will live here.</p><div class="rule"></div><p class="small muted">Packs currently contain Live cards only.</p></div><p class="notice">Design scope: foundation only. No edition creation, issue action or special card is included.</p></section>`;}
function packScreen(){return `${head('packs','Pack store','Three new chances to find a familiar face.')}<div class="columns"><section class="pack"><p class="kicker">The regular pack</p><h2>TFH Pack</h2><p class="muted">Three Live cards from the TFH roster.<br>A new face. An old favorite. Sometimes a spare.</p><div class="price">175 <span style="font-size:14px;letter-spacing:0">KUT Coins</span></div><p class="small muted">3 Live cards · rarity-weighted draws</p>${state.packOpened?`<div class="toast" role="status">Pack opened · 175 KUT Coins spent</div><div class="card-grid section">${['dana','frankie','bea'].map(id=>card(id)).join('')}</div>${link('collection','See collection','btn full')}`:button('open-pack',state.balance>=175?'Open for 175 KUT Coins':`Need ${175-state.balance} more KUT Coin${175-state.balance===1?'':'s'}`,'full',state.balance<175?'disabled':'')}<p class="meta small muted">${state.packOpened?`Wallet now ${state.balance} KUT Coins`:`Your balance ${state.balance} · leaves you ${Math.max(0,state.balance-175)}`}</p></section><aside class="panel"><p class="eyebrow">What is in the ladder</p>${[['common','Common','under 40'],['bronze','Bronze','40–49'],['silver','Silver','50–59'],['gold','Gold','60–69'],['holo','Holo','70–79'],['elite','Elite','80+']].map(([tier,label,ovr])=>`<div class="row"><span class="tier-chip" data-rarity="${tier}"><span class="live-card__tier-icon--${tier}"></span></span><b class="grow">${label}</b><span class="muted small">OVR ${ovr}</span></div>`).join('')}<p class="notice">A Live card can climb the ladder as its player keeps showing up.</p></aside></div>`;}
function valueScreen(){return `${link('collection','← Collection','back')}${head('value','Your collection','Different cards build a stronger collection.')}<div class="columns"><section><p class="eyebrow">Your Club Value</p><div class="big-number">1,236</div><div class="stats"><div><p class="eyebrow">Wallet</p><strong>500</strong></div><div><p class="eyebrow">Collection</p><strong>332</strong></div><div><p class="eyebrow">Personal card</p><strong>404</strong></div></div><p class="small muted">500 + 332 + 404 = 1,236 · 8 cards, 4 different players</p><div class="value-rule"><p class="eyebrow">How copies count</p><div class="weights"><div><small>1st</small><b>100%</b></div><div><small>2nd</small><b>20%</b></div><div><small>3rd</small><b>5%</b></div><div><small>4th+</small><b>0%</b></div></div><p class="small muted">Per edition. Discard payouts stay at their full value.</p></div><div class="section"><div class="section-head"><h2>Your collection's share</h2></div><table class="ledger"><thead><tr><th>Player / edition</th><th>Club Value</th></tr></thead><tbody><tr><td>${link('copies','Alex Example →')}<small>Live · 5 copies · 101 base value</small></td><td>126</td></tr><tr><td>Charlie Fixture<small>Live · 1 copy</small></td><td>101</td></tr><tr><td>Bea Test<small>Live · 1 copy</small></td><td>68</td></tr><tr><td>Dana Demo<small>Live · 1 copy</small></td><td>37</td></tr><tr><td>Collection total</td><td>332</td></tr></tbody></table></div></section><aside class="panel stack"><h2>A different card goes further.</h2><p class="muted small">The first copy does the heavy lifting. A few spares add a little extra.</p><p class="muted small">These weights affect Club Value. Each copy still has its full discard payout.</p>${link('tradecards','Find a home for a spare','btn secondary full')}<div class="rule"></div><p class="eyebrow">Your personal card</p><p><b>Alex Example · 60 OVR</b></p><p class="muted small">101 base value × 4 = <b>404</b><br>Your linked player adds this bonus whether or not you own their card.</p></aside></div>${note('<b>Club Value now favors different cards.</b><br>Your coins and cards have not been removed. Only how duplicate copies count has changed.')}`;}
function copyScreen(){const n=state.count;const total=n>=3?126:n===2?121:n===1?101:0;return `${link('value','← Club Value','back')}${head('copies','Alex Example · Live edition')}<div class="columns"><section><div class="row"><div class="thumb" style="width:90px;flex-basis:90px">${card('alex')}</div><div><h2>${n} copies. ${total} value.</h2><p class="muted small" style="margin-top:10px">Each copy can be discarded for 101 KUT Coins.</p></div></div><table class="ledger section"><thead><tr><th>Copy</th><th>Weight</th><th>Adds to Club Value</th></tr></thead><tbody>${Array.from({length:n},(_,i)=>`<tr><td>Copy ${i+1}</td><td>${[100,20,5][i]??0}%</td><td>${[101,20,5][i]??0}</td></tr>`).join('')}<tr><td>Total</td><td></td><td>${total}</td></tr></tbody></table><div class="actions section">${link('tradecards','Trading preferences','btn')}${button('listing','List a copy','secondary')}${button('discard','Discard a copy','text',state.count<1?'disabled':'')}</div></section><aside class="panel stack"><h2>Keep the one you love.</h2><p class="muted">The fourth copy onward adds no extra Club Value. You can still trade it, list it, or discard it.</p><p class="small muted">If you let the first copy go, another takes its full-value place automatically.</p><div class="rule"></div><label class="label" for="copy-count">Try the calculation · number of copies</label><input class="input" id="copy-count" type="number" min="1" max="10" value="${n}"><p class="small muted">Interactive example only; changing this number does not change a collection.</p></aside></div>`;}
function homeScreen(){return `${head('home','Terrible Football Haarlem','A few familiar faces. A little friendly competition.')}<div class="stats"><div><p class="eyebrow">KUT Coins</p><strong>${state.balance}</strong></div><div><p class="eyebrow">Club Value</p><strong>1,236</strong></div><div><p class="eyebrow">Club rank</p><strong>7</strong></div></div><div class="callout"><div class="headrow"><div><p class="eyebrow">Friday football · your turn</p><h2 style="margin:8px 0">${state.saved?'Your report is saved.':'Goals, and a little kudos.'}</h2><p class="muted small">Reports close Saturday at 21:30.</p></div>${link(state.saved?'saved':'report',state.saved?'View your report':'Add goals & kudos','btn')}</div></div><div class="columns section"><section><div class="section-head"><h2>This week's familiar faces</h2>${link('leaderboard','All players →','btn text')}</div><div class="card-grid">${['alex','bea','ellis'].map(id=>card(id)).join('')}</div></section><aside class="panel stack"><p class="eyebrow">From the club desk</p><h2>The TFH Chronicle</h2><p class="muted">A Friday worth remembering. Goals, good company and the week's card movements.</p>${link('recap','Read the match report →')}<div class="rule"></div><h3>A card you wanted</h3><p class="muted small">Bea is open to trading her Alex card. Contact her to discuss it.</p>${link('wanted','See wanted cards','btn secondary full')}</aside></div>`;}
function simpleScreen(s){if(s==='listing')return `${link('wanted','← Wanted cards','back')}${head('listing','Transfer market · Live edition')}<div class="columns"><div style="max-width:280px">${card('alex')}</div><div class="panel stack"><h2>A familiar face.</h2><p class="muted">Listed by Bea Test · 130 KUT Coins</p>${button('buy-listed','Buy for 130 KUT Coins','full')}<div class="rule"></div><h3>Or make an offer</h3><p class="muted small">Contact each other and agree the terms, then use the existing Offer action on this listing.</p>${button('trade-help','How to use existing offers','secondary full')}</div></div>`;if(s==='offers')return `${head('offers','Transfer market')}${tabs('market','Offers')}<div class="empty"><h2>No offers yet.</h2><p class="muted">Use the Offer action on an existing market listing once you have agreed a trade.</p>${link('market','Browse the market','btn secondary')}</div>`;if(s==='account')return `${head('account','Your account')}<div class="account-links">${link('collection','My card')}${link('value','How KUT works')}${link('attendance','Admin')}${link('wanted','Wanted-card preferences')}${button('signout','Sign out','text')}</div>`;if(s==='messages')return `${head('messages','Club inbox')}<div class="row"><div class="grow"><h3>Your Friday report is ready</h3><p class="muted small">Add your goals and give your teammates a little kudos.</p></div>${link('report','Open · +50 coins','btn secondary')}</div>`;if(s==='leaderboard')return `${head('leaderboard','Club standings')}<table class="ledger"><thead><tr><th>Rank</th><th>Club</th><th>Club Value</th></tr></thead><tbody><tr><td>6</td><td>Bea's Club</td><td>1,310</td></tr><tr><td>7</td><td>Your club</td><td>1,236</td></tr><tr><td>8</td><td>Dana's Club</td><td>1,140</td></tr></tbody></table>${link('value','See your breakdown','btn secondary section')}`;return `${head('collection','Your club','A familiar face in every slot.',link('value','1,236 Club Value →','btn text'))}${tabs('collection','Album')}<div class="card-grid">${['charlie','dana','bea'].map(id=>`<div>${card(id)}</div>`).join('')}<div class="empty"><h2>Alex Example</h2><p class="muted small">An empty spot in your album.</p>${button('want-alex','Want card')}</div></div>`;}
function render(){let s=screen();if(s==='matches'||s==='swap')s='wanted';document.title=`${titles[s]||'KUT'} · KUT design`;const fn={home:homeScreen,wanted:wantScreen,tradecards:tradeCards,market:marketScreen,adminreports:adminReportsScreen,report:reportScreen,saved:savedScreen,recap:recapScreen,attendance:adminAttendance,editions:editionScreen,packs:packScreen,value:valueScreen,copies:copyScreen}[s];app.innerHTML=`${chrome(s)}<main id="main" tabindex="-1">${fn?fn():simpleScreen(s)}${footer()}</main>`;markCurrent();if(s==='report'){updateGoalConfirm();if(new URL(location.href).searchParams.get('state')==='closed'){document.querySelectorAll('#report-form button,#report-form input').forEach(el=>el.disabled=true);document.querySelector('.savearea').innerHTML='<p class="callout"><b>Reports are closed.</b><br>Your saved answers are shown above.</p>'+link('recap','View the match report','btn full');}}}

function markCurrent(){document.querySelectorAll('.primary a.active,.bottomnav a.active').forEach(el=>el.setAttribute('aria-current','page'));}
function go(s){history.pushState(null,'',`?screen=${s}`);render();window.scrollTo(0,0);document.getElementById('main').focus({preventScroll:true});}
function openDialog(title,body){returnFocus=document.activeElement;dialog.innerHTML=`<div class="dialog-inner"><div class="dialog-head"><h2 id="dialog-title">${title}</h2>${button('close','Close','text')}</div>${body}</div>`;dialog.showModal();dialog.querySelector('input,button')?.focus();}
function closeDialog(){dialog.close();returnFocus?.focus();}
function showWantPicker(){openDialog('Add wanted cards',`<p class="muted small">Choose the players you would like to collect.</p><div class="search section">${icon('IconSearch')}<input placeholder="Find a player" aria-label="Search players" data-search="wants"></div><div class="dialog-list" id="wants">${KUT_DESIGN.players.map(p=>`<button class="pick" data-name="${p.displayName.toLowerCase()}" data-act="pick-want:${p.id}" aria-pressed="${state.wants.includes(p.id)}"><span><b>${p.displayName}</b><small>Live edition · ${p.liveOvr} OVR</small></span><span>${state.wants.includes(p.id)?'✓ Added':'+ Add'}</span></button>`).join('')}</div><div class="dialog-foot">${button('done-wants','Done')}</div>`);}
function showNominees(key){state.category=key;openDialog(categories[key],`<p class="muted small">${categoryHelp[key]}</p><div class="search section">${icon('IconSearch')}<input placeholder="Find a teammate" aria-label="Search teammates" data-search="nominees"></div><div class="dialog-list" id="nominees">${KUT_DESIGN.players.filter(p=>p.id!=='alex').map(p=>{const chosen=Object.entries(state.nominees).find(([k,id])=>k!==key&&id===p.id);return `<button class="pick" data-name="${p.displayName.toLowerCase()}" data-act="pick-nominee:${p.id}" ${chosen?'disabled':''}><span><b>${p.displayName}</b><small>${chosen?`Already chosen for ${categories[chosen[0]]}`:'Attended Friday'}</small></span><span>${state.nominees[key]===p.id?'✓':''}</span></button>`;}).join('')}</div><div class="dialog-foot">${button('skip-nominee','Skip this category','secondary')}</div>`);}
function updateGoalConfirm(){const el=document.getElementById('goal-confirm');if(el)el.innerHTML=state.goals>=10?`<label class="checkrow"><input class="checkbox" type="checkbox" id="confirm-goals">Confirm ${state.goals} goals</label>`:'';}
document.addEventListener('click',event=>{const a=event.target.closest('a');if(a?.getAttribute('href')?.startsWith('?screen=')){event.preventDefault();go(a.getAttribute('href').slice(8));return;}const el=event.target.closest('[data-act]');if(!el||el.disabled)return;const [act,id]=el.dataset.act.split(':');if(act==='close'){closeDialog();return;}if(act==='add-wants'){showWantPicker();return;}if(act==='pick-want'){state.wants=state.wants.includes(id)?state.wants.filter(x=>x!==id):[...state.wants,id];el.setAttribute('aria-pressed',String(state.wants.includes(id)));el.lastElementChild.textContent=state.wants.includes(id)?'✓ Added':'+ Add';return;}if(act==='done-wants'){closeDialog();render();return;}if(act==='remove-want'){state.wants=state.wants.filter(x=>x!==id);render();return;}if(act==='available'){state.available=state.available.includes(id)?state.available.filter(x=>x!==id):[...state.available,id];render();return;}if(act==='goal'){state.goals=Number(id);document.querySelectorAll('.goal').forEach(b=>b.setAttribute('aria-pressed',String(b===el)));document.getElementById('goal-count').value='';updateGoalConfirm();return;}if(act==='nominate'){showNominees(id);return;}if(act==='pick-nominee'||act==='skip-nominee'){if(act==='pick-nominee')state.nominees[state.category]=id;else state.nominees[state.category]=null;closeDialog();render();return;}if(act==='buy-listed'){openDialog('Buy Alex Example?',`<p class="muted">130 KUT Coins · leaves you ${state.balance-130}</p><p class="notice">This previews an existing market action; no purchase is submitted.</p><div class="dialog-foot">${button('close','Back to listing','secondary')}</div>`);return;}if(act==='open-pack'){openDialog('Open a TFH Pack?',`<p class="muted">Three Live cards for 175 KUT Coins.</p><table class="ledger section"><tbody><tr><td>Your balance</td><td>${state.balance}</td></tr><tr><td>Pack price</td><td>−175</td></tr><tr><td>Balance after opening</td><td>${state.balance-175}</td></tr></tbody></table><div class="dialog-foot">${button('confirm-pack','Confirm · 175 KUT Coins')}</div>`);return;}if(act==='confirm-pack'){if(!state.packOpened&&state.balance>=175){state.balance-=175;state.packOpened=true;}closeDialog();render();return;}if(act==='want-alex'){if(!state.wants.includes('alex'))state.wants.push('alex');el.textContent='✓ On your wanted list';return;}if(act==='discard'){const delta=state.count>=4?101:state.count===3?96:state.count===2?81:0;openDialog('Discard one copy?',`<p>Receive <b>101 KUT Coins</b>. This copy is permanently removed.</p><p class="muted section">After the remaining copies are reweighted, your total Club Value ${delta?`increases by ${delta}`:'stays the same'}.</p><div class="dialog-foot">${button('demo-discard','Discard for 101 KUT Coins','danger')}</div>`);return;}if(act==='demo-discard'){if(state.count<1)return;closeDialog();state.count=Math.max(0,state.count-1);state.balance+=101;render();return;}if(act==='listing'){openDialog('List a copy',`<label class="label" for="listing-price">Asking price · KUT Coins</label><input class="input" id="listing-price" type="number" value="130" min="80" max="760"><p class="muted small section">A listing stays open for 24 hours. This design does not create a real listing.</p><div class="dialog-foot">${button('close','Done','secondary')}</div>`);return;}if(act==='signout'){openDialog('Design preview',`<p class="muted">No account is signed in. This is a fictional design session.</p>`);}});
document.addEventListener('input',event=>{const el=event.target;if(el.dataset.search){document.querySelectorAll(`#${el.dataset.search} [data-name]`).forEach(row=>row.hidden=!row.dataset.name.includes(el.value.toLowerCase()));}if(el.id==='goal-count'){const raw=el.value;state.goals=raw===''?null:/^\d{1,2}$/.test(raw)?Number(raw):NaN;document.querySelectorAll('.goal').forEach(b=>b.setAttribute('aria-pressed','false'));updateGoalConfirm();}});
document.addEventListener('change',event=>{if(event.target.id==='copy-count'){state.count=Math.min(10,Math.max(1,Number(event.target.value)||1));render();}});
document.addEventListener('submit',event=>{if(event.target.id==='report-form'){event.preventDefault();const invalid=Number.isNaN(state.goals)||(state.goals>=10&&!document.getElementById('confirm-goals')?.checked)||state.goals===null||!Object.keys(categories).every(k=>Object.hasOwn(state.nominees,k));if(invalid){const err=document.getElementById('report-error');err.innerHTML='<p class="error" role="alert" tabindex="-1">Enter your goals and choose or skip every kudos category. Confirm your goal count if it is 10 or higher.</p>';err.firstElementChild.focus();return;}if(!state.saved)state.balance+=50;state.saved=true;go('saved');}if(event.target.id==='attendance-form'){event.preventDefault();const count=document.querySelectorAll('[name=attendee]:checked').length;document.getElementById('attendance-status').innerHTML=`<div class="toast" role="status">Preview: ${count} attendees published. Their 24-hour report window is open.</div>`;}});
dialog.addEventListener('close',()=>returnFocus?.focus());
window.addEventListener('popstate',render);
if(screen()==='saved'||new URL(location.href).searchParams.get('state')==='closed'){state.goals=2;state.nominees={team:'bea',wall:'dana',vibes:null};state.saved=true;state.balance=550;}
if(new URL(location.href).searchParams.get('state')==='empty')state.wants=[];
if(new URL(location.href).searchParams.get('state')==='insufficient')state.balance=174;
render();

function adminRecords(){return state.adminRecords??=(
  [{id:'alex',status:'Submitted',goals:2,source:'Member',reward:true},
   {id:'bea',status:'Submitted',goals:0,source:'Member',reward:true},
   {id:'charlie',status:'Pending',goals:null,source:null,reward:false},
   {id:'dana',status:'Pending',goals:null,source:null,reward:false},
   {id:'ellis',status:'No account',goals:null,source:null,reward:false},
   {id:'frankie',status:'No account',goals:1,source:'Admin',reward:false}]);}
function adminReportsScreen(){const rows=adminRecords();const filter=state.reportFilter??'All';return `${link('attendance','← Attendance','back')}${head('adminreports','Friday football · 4 September')}<div class="stats"><div><p class="eyebrow">Forms completed</p><strong>2 / 4</strong></div><div><p class="eyebrow">No account</p><strong>2</strong></div><div><p class="eyebrow">Rewards paid</p><strong>100</strong></div></div><p class="muted small">6 attendees · ${rows.filter(r=>r.goals!==null).length} goal counts recorded. Admin goal entry does not complete a member's form.</p><div class="actions section" aria-label="Report filters">${['All','Pending','No account'].map(label=>button('report-filter:'+label,label,'secondary',`aria-pressed="${filter===label}"`)).join('')}</div><div class="search section">${icon('IconSearch')}<input aria-label="Search reports" data-search="admin-report-list" placeholder="Find an attendee"></div><div class="columns section"><section id="admin-report-list">${rows.filter(r=>filter==='All'||r.status===filter).map(r=>`<div class="admin-report-row" data-name="${player(r.id).displayName.toLowerCase()}"><div><h3>${player(r.id).displayName}</h3><p class="small ${r.status==='Submitted'?'positive':'muted'}">${r.status}${r.status==='Submitted'?' · Fri 22:10':''}</p><p class="muted small">${r.reward?'50 coins paid':r.status==='No account'?'No account · no form reward':'Reward not earned'}</p></div><div class="goal-source"><b>${r.goals??'—'}</b><small>${r.source??'No goals'}</small></div>${button('edit-admin-goals:'+r.id,r.goals===null?'Add goals':'Edit goals','secondary')}</div>`).join('')}</section><aside class="panel stack"><h2>Everyone's evening counts.</h2><p class="muted">Record goals for attendees without an account, or correct a member's submitted count.</p><p class="small muted">Changes need a reason and stay in the history. They do not pay another reward or fill in kudos for someone.</p><p class="small muted">After reports close, a correction also updates Form, Shooting and the Chronicle.</p></aside></div>`;}
document.addEventListener('click',async event=>{const el=event.target.closest('[data-act]');if(!el)return;const [act,id]=el.dataset.act.split(':');
 if(act==='conversation'){const message="Hi Bea, I saw you're open to trading your Live Alex card on KUT. Shall we agree a trade?";try{await navigator.clipboard.writeText(message);document.getElementById('availability-status').innerHTML='<p class="toast" role="status">Copied · send it to the owner.</p>';}catch{openDialog('Message for Bea',`<p class="muted small">Copy this text and send it to the owner.</p><textarea class="input section" rows="4" readonly aria-label="Message to copy">${esc(message)}</textarea>`);} }
 if(act==='refresh-availability'){document.getElementById('availability-status').innerHTML='<p class="toast" role="status">Availability refreshed.</p>';}
 if(act==='trade-help'){openDialog('Agree the terms',`<div class="stack"><p>1. Contact the member and agree which cards or coins you want to exchange.</p><p>2. The owner lists their card in the Market.</p><p>3. Open that listing and use its existing Offer action. The owner can accept there.</p><p class="callout">A listing is public and can be bought by someone else. A conversation does not reserve it.</p></div>`);}
 if(act==='save-draft'){document.getElementById('report-error').innerHTML='<p class="toast" role="status">Draft saved. Complete the form to receive 50 coins.</p>';}
 if(act==='report-filter'){state.reportFilter=id;render();}
 if(act==='edit-admin-goals'){state.adminEditing=id;const row=adminRecords().find(r=>r.id===id);openDialog(row.goals===null?'Add goals':'Edit goals',`<p><b>${player(id).displayName}</b></p><p class="muted small">${row.status} · current count: ${row.goals??'not recorded'} (${row.source??'no source'})</p><form id="admin-goals-form" class="section"><label class="label" for="admin-goals">Goals scored</label><input class="input" id="admin-goals" type="number" min="0" max="99" required value="${row.goals??''}"><label class="label section" for="admin-goals-reason">Reason for this change</label><input class="input" id="admin-goals-reason" maxlength="200" required placeholder="For example: confirmed after football"><p class="muted small section">The original report stays in history. Completion and rewards stay the same.</p><div id="admin-goals-error"></div><div class="dialog-foot"><button class="btn full" type="submit">Save goals</button></div></form>`);}
});
document.addEventListener('submit',event=>{if(event.target.id!=='admin-goals-form')return;event.preventDefault();const goals=Number(document.getElementById('admin-goals').value),reason=document.getElementById('admin-goals-reason').value.trim();if(!Number.isInteger(goals)||goals<0||goals>99||!reason){document.getElementById('admin-goals-error').innerHTML='<p class="error" role="alert">Enter a valid goal count and a reason.</p>';return;}const row=adminRecords().find(r=>r.id===state.adminEditing);row.originalGoals??=row.goals;row.goals=goals;row.source='Admin';row.reason=reason;closeDialog();render();});
